const $ = (s) => document.querySelector(s); const $$ = (s) => [...document.querySelectorAll(s)];
const toast = (message) => { const el = $('#toast'); el.textContent = message; el.classList.add('show'); setTimeout(() => el.classList.remove('show'), 2200); };
const icons = () => window.lucide?.createIcons(); icons();
const showSheet = (sheet) => { $('#scrim').classList.add('show'); sheet.classList.add('open'); sheet.setAttribute('aria-hidden','false'); };
const hideSheets = () => { $('#scrim').classList.remove('show'); $$('.sheet').forEach(s=>{s.classList.remove('open');s.setAttribute('aria-hidden','true');}); };
$('#creatorButton').addEventListener('click',()=>showSheet($('#creatorSheet'))); $('#filterButton').addEventListener('click',()=>showSheet($('#filterSheet'))); $$('[data-close-sheet]').forEach(btn=>btn.addEventListener('click',hideSheets)); $('#scrim').addEventListener('click',hideSheets);
let following=false; const updateFollow=()=>{const label=following?'Following':'Follow'; $('#followButton span').textContent=label; $('#sheetFollowButton span').textContent=label; toast(following?'You are following Khaled':'Unfollowed Khaled');}; $('#followButton').addEventListener('click',()=>{following=!following;updateFollow();}); $('#sheetFollowButton').addEventListener('click',()=>{following=!following;updateFollow();}); $('#messageButton').addEventListener('click',()=>toast('Message composer opened')); $('#shareButton').addEventListener('click',async()=>{ try { await navigator.clipboard.writeText(location.href); toast('Link copied'); } catch { toast('Share link ready'); } });
$$('.tab').forEach(tab=>tab.addEventListener('click',()=>{ $$('.tab').forEach(t=>t.classList.remove('active'));tab.classList.add('active');$$('.view').forEach(v=>v.classList.remove('active-view'));$(`#${tab.dataset.view}View`).classList.add('active-view');}));
$$('.browse-option').forEach(btn=>btn.addEventListener('click',()=>{ $$('.browse-option').forEach(b=>b.classList.remove('active'));btn.classList.add('active');const all=btn.dataset.mode==='all';$('#collectionMode').hidden=all;$('#allMode').hidden=!all; }));
$$('.filter-chip').forEach(chip=>chip.addEventListener('click',()=>chip.classList.toggle('selected'))); $('#applyFilters').addEventListener('click',()=>{hideSheets();toast('Filters applied');});
$$('.see-all').forEach(btn=>btn.addEventListener('click',()=>{document.querySelector('[data-mode="all"]').click();toast(`${btn.dataset.collection} opened`);}));$('#backToPlaces').addEventListener('click',()=>document.querySelector('[data-view="places"]').click());
$$('.image-wrap button,.list-card>button').forEach(btn=>btn.addEventListener('click',()=>{btn.classList.toggle('saved');toast(btn.classList.contains('saved')?'Place saved':'Place removed from saves');}));
const header=$('#iosHeader'); const hero=$('.list-hero'); const toggleHeader=()=>header.classList.toggle('scrolled',window.scrollY>hero.offsetTop+hero.offsetHeight-110);toggleHeader();window.addEventListener('scroll',toggleHeader,{passive:true});
if (new URLSearchParams(location.search).get('slide') === 'creator') showSheet($('#creatorSheet'));
